  void ScenarioLayout(bool on){var t=editor.Parent as TableLayoutPanel;if(t!=null){t.ColumnStyles[1].Width=on?67:54;t.ColumnStyles[2].Width=on?33:46;}}
  void SelectBox(FlowLayoutPanel f,string label,IEnumerable<Choice> items,string current,Action<string> change,int width){f.Controls.Add(Theme.Label(label,9,true));var cb=Theme.Combo();cb.Width=width;foreach(var c in items)cb.Items.Add(c);cb.SelectedItem=cb.Items.Cast<Choice>().FirstOrDefault(x=>x.Key==current);cb.SelectedIndexChanged+=(s,e)=>{if(cb.SelectedItem!=null){change(((Choice)cb.SelectedItem).Key);Mark();}};f.Controls.Add(cb);}
