  void ShowChain(){if(chain==null)return;insertion=chain.Blocks;RenderChain();ShowPalette();}
  void RenderChain(){if(chain==null)return;var f=Begin(chain.Name,"Собирайте логику сверху вниз. Вложенные блоки выполняются внутри своей рамки.");int w=Math.Max(390,editor.ClientSize.Width-65);SmallField(f,"Название сценария",chain.Name,v=>{chain.Name=v;UpdateObjectCaption(chain);},w);var enabled=new UiCheckBox{Text="Сценарий включён",AutoSize=true,Checked=chain.Enabled,ForeColor=Theme.Text};enabled.CheckedChanged+=(s,e)=>{chain.Enabled=enabled.Checked;Mark();};f.Controls.Add(enabled);SelectBox(f,"КОГДА",EventNames.Select(x=>new Choice(x.Key,x.Value)),chain.Event,v=>{chain.Event=v;if(v=="timer"||v=="game_start")chain.Source="";RenderChain();},w);if(chain.Event!="timer"&&chain.Event!="game_start")SelectBox(f,"Источник события",new[]{new Choice("","Любой источник")}.Concat(project.Entities.Select(x=>new Choice(x.Key,x.NameRu+" · "+x.Key))),chain.Source,v=>chain.Source=v,w);if(chain.Event=="timer")SmallNumber(f,"Период таймера, с (общий для сценария)",chain.Interval,.05,3600,v=>chain.Interval=v,150);var root=Theme.Button("＋ Добавлять в корень",()=>{insertion=chain.Blocks;scenarioPane="blocks";ShowPalette();});f.Controls.Add(root);DrawBlocks(f,chain.Blocks,0,w);f.Controls.Add(Theme.Button("Удалить сценарий",()=>{project.Chains.Remove(chain);Mark();Switch("actions");}));objectViewActive=true;}
  void DrawBlocks(FlowLayoutPanel host,List<Block> list,int depth,int width){foreach(var block in list.ToArray()){var b=block;int index=list.IndexOf(b);Color color=b.Kind=="if"||b.Kind=="condition"?Color.FromArgb(61,174,160):b.Kind=="loop"||b.Kind=="delay"?Color.FromArgb(225,160,65):Color.FromArgb(145,119,229);var outer=new Panel{Width=width,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,BackColor=color,Padding=new Padding(4,0,0,0),Margin=new Padding(0,6,0,5)};var card=new FlowLayoutPanel{FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoSize=true,AutoSizeMode=AutoSizeMode.GrowAndShrink,Width=width-4,Padding=new Padding(12),BackColor=Theme.Input};outer.Controls.Add(card);card.Location=new Point(4,0);int inner=width-43;var bar=new FlowLayoutPanel{Width=inner,AutoSize=true};var title=Theme.Label((depth+1)+"  ·  "+(b.Kind=="if"?"ЕСЛИ / ИНАЧЕ":b.Kind=="condition"?"УСЛОВИЕ":b.Kind=="loop"?"ЦИКЛ":b.Kind=="delay"?"ПОДОЖДАТЬ":b.Kind=="group"?"ГРУППА":"ДЕЙСТВИЕ"),9,true);title.ForeColor=color;bar.Controls.Add(title);bar.Controls.Add(Tiny("↑",()=>{if(index>0){list.Remove(b);list.Insert(index-1,b);Mark();RenderChain();}}));bar.Controls.Add(Tiny("↓",()=>{if(index<list.Count-1){list.Remove(b);list.Insert(index+1,b);Mark();RenderChain();}}));bar.Controls.Add(Tiny("×",()=>{list.Remove(b);Mark();RenderChain();}));card.Controls.Add(bar);
    if(b.Kind=="action"||b.Kind=="condition"||b.Kind=="if")SelectBox(card,"",(b.Kind=="action"?Actions:Conditions).Select(x=>new Choice(x.Key,x.Value)),b.Type,v=>{b.Type=v;b.Value=VariableBlock(b)?project.Variables.Select(x=>x.Name).FirstOrDefault()??"":"";b.Operation="set";if(!VariableTools.UsesNumber(b)){b.Expression="";b.Text="";}RenderChain();},inner);
    if(b.Kind=="loop")SelectBox(card,"Режим цикла",new[]{new Choice("repeat","Повторить N раз"),new Choice("while","Пока переменная соответствует условию")},b.Type,v=>{b.Type=v;RenderChain();},inner);
    if(VariableBlock(b)){var choices=project.Variables.Select(v=>new Choice(v.Name,v.Name+" · "+VariableTools.TypeLabel(v.Type)+(v.Scope=="global"?" · общая":" · у каждого объекта"))).ToList();if(!String.IsNullOrEmpty(b.Value)&&!project.Variables.Any(v=>v.Name==b.Value))choices.Insert(0,new Choice(b.Value,"Не найдена: "+b.Value));SelectBox(card,"Переменная",choices,b.Value,v=>{b.Value=v;b.Operation="set";if(!VariableTools.UsesNumber(b)){b.Expression="";b.Text="";}RenderChain();},inner);if(project.Variables.Count==0)card.Controls.Add(Theme.Button("＋ Создать переменную",()=>VariableDialog(null)));}
    else if(b.Type=="sound"||b.Type=="loop_sound")SelectBox(card,"Звук",project.Sounds.Select(v=>new Choice(v.Id,v.Name)),b.Value,v=>b.Value=v,inner);
    else if(b.Type=="convert_projectile"||b.Type=="spawn_projectile"||b.Type=="fragments")SelectBox(card,"Тип снаряда",project.Entities.Where(x=>x.Kind=="projectiles").Select(x=>new Choice(x.Key,x.NameRu)).Concat(Catalog.Templates.Where(x=>x.Kind=="projectiles").Select(x=>new Choice(x.Key,"Игра: "+x.Name))),b.Value,v=>b.Value=v,inner);
    else if(b.Type=="device")SelectBox(card,"Сооружение",project.Entities.Where(x=>x.Kind=="devices").Select(x=>new Choice(x.Key,x.NameRu)),b.Value,v=>b.Value=v,inner);
    else if(b.Type=="material"||b.Type=="source"||b.Type=="effect")SmallField(card,b.Type=="effect"?"Путь к эффекту, например effects/impact_heavy.lua":"SaveName",b.Value,v=>b.Value=v,inner);
    if(b.Type=="variable"||b.Type=="hp"||b.Kind=="loop"&&b.Type=="while"){bool listValue=b.Type!="hp"&&project.Variables.Any(v=>v.Name==b.Value&&v.Type=="list");SelectBox(card,"Сравнение",(listValue?new[]{"==","~="}:new[]{">=","<=","==","~=",">","<"}).Select(x=>new Choice(x,x)),b.Operator,v=>b.Operator=v,110);}
    if(b.Type=="edit_var")DrawVariableAction(card,b,inner);
    bool numeric=b.Kind=="loop"||b.Kind=="delay"||new[]{"variable","hp","chance","set_var","add_var","multiply_var","fire","damage","convert_projectile","spawn_projectile","fragments","set_projectile_hp","alpha","sound","loop_sound"}.Contains(b.Type);
    if(numeric){string label=b.Kind=="delay"?"Пауза, с":b.Kind=="loop"&&b.Type=="repeat"?"Количество повторов":b.Type=="convert_projectile"?"Коэффициент скорости · 0,65 = 65%":b.Type=="sound"||b.Type=="loop_sound"?"Громкость блока, %":b.Type=="chance"?"Вероятность, %":"Значение";if(b.Type=="fragments"||b.Type=="sound"||b.Type=="loop_sound"){SmallNumber(card,label,b.Number,0,b.Type=="fragments"?100000000:200,v=>b.Number=v,160);if(b.Type=="fragments")SmallField(card,"Разброс StdDev",b.Text,v=>b.Text=v,inner);}else{string old=!String.IsNullOrWhiteSpace(b.Text)?b.Text:b.Number.ToString("R",CultureInfo.InvariantCulture);BlockFormulaField(card,label,!String.IsNullOrEmpty(b.Expression)?b.Expression:old,v=>{b.Expression=v;b.Text="";},inner,null,project.Variables.Any(x=>x.Name==b.Value&&x.Type=="list")&&(b.Type=="variable"||b.Type=="set_var"||b.Kind=="loop"&&b.Type=="while"));}}
    if(b.Kind=="loop")SmallNumber(card,"Пауза между повторениями, с · минимум 0,05",b.Number2,.05,3600,v=>b.Number2=v,160);
    if(b.Type=="spawn_projectile")SmallNumber(card,"Начальная скорость",b.Number2,0,100000,v=>b.Number2=v,160);
    if(b.Type=="loop_sound"||b.Type=="stop_sound")SmallField(card,"Канал: одинаковое имя заменяет предыдущий звук",b.Tag,v=>b.Tag=v,inner);
    if(new[]{"if","loop","delay","group"}.Contains(b.Kind)){card.Controls.Add(Theme.Button("＋ Внутрь блока",()=>{insertion=b.Children;scenarioPane="blocks";ShowPalette();}));DrawBlocks(card,b.Children,depth+1,inner);if(b.Kind=="if"){card.Controls.Add(Theme.Label("ИНАЧЕ",9,true));card.Controls.Add(Theme.Button("＋ В ветку «иначе»",()=>{insertion=b.Otherwise;scenarioPane="blocks";ShowPalette();}));DrawBlocks(card,b.Otherwise,depth+1,inner);}}
    foreach(Control label in card.Controls)if(label is Label)((Label)label).MaximumSize=new Size(Math.Max(80,inner),0);host.Controls.Add(outer);
   }}
  Button Tiny(string text,Action a){var b=Theme.Button(text,a);b.AutoSize=false;b.MinimumSize=new Size(28,27);b.Size=new Size(28,27);b.Padding=Padding.Empty;return b;}
  void Insert(Block b){if(chain==null)return;if(insertion==null)insertion=chain.Blocks;insertion.Add(b);Mark();RenderChain();}
  void ShowPalette(){
   ClearUi(right);
   var body=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1,BackColor=Theme.Card,Margin=Padding.Empty,Padding=Padding.Empty};body.RowStyles.Add(new RowStyle(SizeType.AutoSize));body.RowStyles.Add(new RowStyle(SizeType.Percent,100));right.Controls.Add(body);
   var tabs=new FlowLayoutPanel{AutoSize=true,Dock=DockStyle.Fill,WrapContents=true,Padding=new Padding(10,8,10,5),Margin=Padding.Empty};
   tabs.Controls.Add(Theme.Button("Переменные",()=>{scenarioPane="variables";ShowPalette();},scenarioPane=="variables"));tabs.Controls.Add(Theme.Button("Блоки и ресурсы",()=>{scenarioPane="blocks";ShowPalette();},scenarioPane=="blocks"));tabs.Controls.Add(Theme.Button("Гайд по формулам",ShowFormulaGuide));body.Controls.Add(tabs,0,0);
   var f=Theme.Flow(true);body.Controls.Add(f,0,1);int w=Math.Max(220,right.ClientSize.Width-58);
   if(scenarioPane=="variables")DrawVariablesPane(f,w);else DrawBlockPalette(f,w);
   Action size=()=>{int next=Math.Max(160,f.ClientSize.Width-f.Padding.Horizontal-SystemInformation.VerticalScrollBarWidth-4);foreach(Control control in f.Controls){if(control is Label)((Label)control).MaximumSize=new Size(next,0);else if(control is Panel||control is TextBox||control is ComboBox)control.Width=next;}};f.SizeChanged+=(s,e)=>size();size();
  }
  void DrawBlockPalette(FlowLayoutPanel f,int w){
   f.Controls.Add(Theme.Label("Блоки и ресурсы",18,true));var info=Theme.Label(chain==null?"Создайте сценарий слева.":"Добавление: "+(insertion==chain.Blocks?"корень сценария":"выбранная вложенная ветка"),9);info.MaximumSize=new Size(w,0);f.Controls.Add(info);
   Header(f,"Логика");f.Controls.Add(Theme.Button("Если / иначе",()=>Insert(new Block{Kind="if",Type="variable",Value=project.Variables.Select(x=>x.Name).FirstOrDefault()??"",Number=0})));f.Controls.Add(Theme.Button("Повторить",()=>Insert(new Block{Kind="loop",Type="repeat",Number=3,Number2=.2})));f.Controls.Add(Theme.Button("Пока",()=>Insert(new Block{Kind="loop",Type="while",Value=project.Variables.Select(x=>x.Name).FirstOrDefault()??"",Number=3,Operator="<",Number2=.2})));f.Controls.Add(Theme.Button("Пауза",()=>Insert(new Block{Kind="delay",Type="delay",Number=1})));f.Controls.Add(Theme.Button("Группа",()=>Insert(new Block{Kind="group",Type="group"})));f.Controls.Add(Theme.Button("Условие для всей ветки",()=>Insert(new Block{Kind="condition",Type="enemy"})));f.Controls.Add(Theme.Button("Действие",()=>Insert(new Block{Kind="action",Type="effect"})));f.Controls.Add(Theme.Button("Редактировать переменную",()=>Insert(new Block{Kind="action",Type="edit_var",Value=project.Variables.Select(x=>x.Name).FirstOrDefault()??"",Operation="set",Expression=project.Variables.FirstOrDefault()!=null&&project.Variables[0].Type=="list"?"[]":"0"})));
   Header(f,"Готовые сценарии");f.Controls.Add(Theme.Button("Повреждение снаряда",DamagePreset));f.Controls.Add(Theme.Button("Счётчик с повторением",CounterPreset));f.Controls.Add(Theme.Label("Переменные доступны по имени: $counter. Условие проверяется при входе в ветку. Циклы выполняются с паузами; предел — 10 000 повторений и 12 уровней вложенности.",9));
   Header(f,"Библиотека звуков");foreach(var sound in project.Sounds.ToArray()){var a=sound;f.Controls.Add(Theme.Button(a.Name,()=>SoundDialog(a)));f.Controls.Add(Theme.Button("Удалить звук",()=>{project.Sounds.Remove(a);Mark();ShowPalette();}));}f.Controls.Add(Theme.Button("＋ Звук WAV / MP3",()=>{var a=new AudioClip{Name="Новый звук"};project.Sounds.Add(a);SoundDialog(a);Mark();ShowPalette();}));foreach(Control label in f.Controls)if(label is Label)((Label)label).MaximumSize=new Size(w,0);
  }
  void SoundDialog(AudioClip a){selected=null;using(var dlg=new UiForm{Text="Звук сценария",ClientSize=new Size(570,620),BackColor=Theme.Card,ForeColor=Theme.Text,StartPosition=FormStartPosition.CenterParent}){var f=Theme.Flow(true);dlg.Controls.Add(f);Action refresh=null;refresh=()=>{ClearUi(f);SmallField(f,"Название",a.Name,v=>a.Name=v,480);DrawAudio(f,"Звук",a,Mark,true,refresh);};refresh();dlg.FormClosed+=(s,e)=>AudioTools.Stop();dlg.ShowDialog(this);}}
  void CounterPreset(){var name="counter";if(!project.Variables.Any(v=>v.Name==name))project.Variables.Add(new Variable{Name=name,Scope="global",Type="int"});var loop=new Block{Kind="loop",Type="repeat",Number=5,Number2=.5};loop.Children.Add(new Block{Kind="action",Type="add_var",Value=name,Number=1});var c=new Chain{Name="Счётчик: пять повторений",Event="game_start"};c.Blocks.Add(loop);project.Chains.Add(c);Mark();Switch("actions",c);}
  void DamagePreset(){var original=project.Entities.FirstOrDefault(e=>e.Kind=="projectiles");if(original==null){UiDialogs.Show("Сначала создайте снаряд.");return;}var copy=Storage.Json().Deserialize<Entity>(Storage.Json().Serialize(original));copy.Key=original.Key+"_damaged";int n=2;while(project.Entities.Any(x=>x.Key==copy.Key))copy.Key=original.Key+"_damaged_"+(n++);copy.NameRu=original.NameRu+" · повреждённый";copy.NameEn=original.NameEn+" damaged";copy.Values["ProjectileDamage"]=original.V("ProjectileDamage",100)*.5;copy.Values["ProjectileSplashDamage"]=original.V("ProjectileSplashDamage",0)*.5;copy.FiniteAmmo=false;project.Entities.Add(copy);var c=new Chain{Name="Повреждение: "+original.NameRu,Event="projectile_hit",Source=original.Key};c.Blocks.Add(new Block{Kind="action",Type="convert_projectile",Value=copy.Key,Number=.65});project.Chains.Add(c);Mark();Switch("actions",c);UiDialogs.Show("Создан повреждённый тип: 50% урона, 65% скорости при переходе. Загрузите другой звук полёта во вкладке ресурсов этого снаряда. Для появления снаряд должен пережить столкновение; настройте AntiAirHitpoints. Преобразование требует High Seas.","Готовый сценарий");}
